    12	const CreateAmenityBody = Type.Object(
    13	  {
    14	    name: Type.String({ minLength: 1, maxLength: 80 }),
    15	    description: Type.Optional(Type.String({ maxLength: 200 })),
    16	  },
    17	  { additionalProperties: false },
    18	);
    19	
    20	const AmenityIdParams = Type.Object({ id: Type.String({ minLength: 1 }) });
    21	
