import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { createTestApp, resetDb } from '/app/tests/helpers/app.js';

const HOUR = 3_600_000;
const inHours = (h: number) => new Date(Date.now() + h * HOUR).toISOString();

describe('repro', () => {
  let app: FastifyInstance, roomId: string, userId: string;
  beforeAll(async () => { app = await createTestApp(); });
  afterAll(async () => { await app.close(); });
  beforeEach(async () => {
    await resetDb();
    roomId = (await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })).json().id;
    userId = (await app.inject({ method: 'POST', url: '/users', payload: { name: 'Ada', email: 'a@b.com' } })).json().id;
  });
  const book = (s: number, e: number, t = 'Sync', extra = {}) => app.inject({
    method: 'POST', url: '/bookings',
    payload: { roomId, userId, title: t, startsAt: inHours(s), endsAt: inHours(e), ...extra },
  });

  it('A: new booking starting before and ending inside existing', async () => {
    await book(24, 25);
    const r = await book(23, 24.5, 'Overlap-left');
    console.log('A ->', r.statusCode, r.body);
  });
  it('B: new booking enclosing existing', async () => {
    await book(24, 25);
    const r = await book(23, 26, 'Enclosing');
    console.log('B ->', r.statusCode, r.body);
  });
  it('C: endsAt before startsAt', async () => {
    const r = await book(25, 24, 'Backwards');
    console.log('C ->', r.statusCode, r.body);
  });
  it('D: zero length', async () => {
    const r = await book(24, 24, 'Zero');
    console.log('D ->', r.statusCode, r.body);
  });
  it('E: in the past', async () => {
    const r = await book(-48, -47, 'Past');
    console.log('E ->', r.statusCode, r.body);
  });
  it('F: unknown room', async () => {
    const r = await app.inject({ method: 'POST', url: '/bookings', payload: { roomId: 'nope', userId, title: 'X', startsAt: inHours(24), endsAt: inHours(25) } });
    console.log('F ->', r.statusCode, r.body);
  });
  it('G: unknown user', async () => {
    const r = await app.inject({ method: 'POST', url: '/bookings', payload: { roomId, userId: 'nope', title: 'X', startsAt: inHours(24), endsAt: inHours(25) } });
    console.log('G ->', r.statusCode, r.body);
  });
  it('H: PATCH onto an occupied slot', async () => {
    const first = await book(24, 25);
    const second = await book(30, 31, 'Second');
    const r = await app.inject({ method: 'PATCH', url: `/bookings/${second.json().id}`, payload: { startsAt: inHours(24), endsAt: inHours(25) } });
    console.log('H ->', r.statusCode, r.body, 'first=', first.json().id);
  });
  it('I: PATCH to backwards period', async () => {
    const first = await book(24, 25);
    const r = await app.inject({ method: 'PATCH', url: `/bookings/${first.json().id}`, payload: { endsAt: inHours(20) } });
    console.log('I ->', r.statusCode, r.body);
  });
  it('J: PATCH to unknown room', async () => {
    const first = await book(24, 25);
    const r = await app.inject({ method: 'PATCH', url: `/bookings/${first.json().id}`, payload: { roomId: 'nope' } });
    console.log('J ->', r.statusCode, r.body);
  });
  it('K: unknown extra property', async () => {
    const r = await book(24, 25, 'Extra', { status: 'CANCELLED' });
    console.log('K ->', r.statusCode, r.body);
  });
  it('L: concurrent identical bookings', async () => {
    const [x, y] = await Promise.all([book(40, 41, 'One'), book(40, 41, 'Two')]);
    console.log('L ->', x.statusCode, y.statusCode);
  });
});
