import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { isBefore, MINUTE_IN_MS, parseInstant } from '../../shared/time.js';
import * as roomsRepository from '../rooms/repository.js';
import * as usersRepository from '../users/repository.js';
import * as repository from './repository.js';
import { BOOKING_ACTIVE, BOOKING_CANCELLED } from './schema.js';
import type { CreateBookingInput, ListBookingsInput, UpdateBookingInput } from './schema.js';

// A request spends some time in flight, so a start that is a hair behind the
// clock is still a request for "now" and not a request for the past.
const PAST_TOLERANCE_MS = MINUTE_IN_MS;

interface Period {
  startsAt: Date;
  endsAt: Date;
}

function assertEndsAfterStart(period: Period): void {
  if (!isBefore(period.startsAt, period.endsAt)) {
    throw validationFailed('Booking must end after it starts', {
      startsAt: period.startsAt.toISOString(),
      endsAt: period.endsAt.toISOString(),
    });
  }
}

function assertNotInThePast(startsAt: Date): void {
  if (startsAt.getTime() < Date.now() - PAST_TOLERANCE_MS) {
    throw validationFailed('Booking cannot start in the past', {
      startsAt: startsAt.toISOString(),
    });
  }
}

async function assertRoomExists(roomId: string): Promise<void> {
  if (!(await roomsRepository.findById(roomId))) {
    throw notFound('Room');
  }
}

async function assertUserExists(userId: string): Promise<void> {
  if (!(await usersRepository.findById(userId))) {
    throw notFound('User');
  }
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);

  assertEndsAfterStart({ startsAt, endsAt });
  assertNotInThePast(startsAt);
  await assertRoomExists(input.roomId);
  await assertUserExists(input.userId);

  // The existence checks above run on the pooled client; everything inside the
  // transaction must use tx, or it would wait on the connection the
  // transaction itself is holding.
  return repository.transaction(async (tx) => {
    const conflict = await repository.findOverlapping(
      { roomId: input.roomId, startsAt, endsAt },
      tx,
    );
    if (conflict) {
      throw bookingConflict(conflict.id);
    }

    return repository.create(
      {
        roomId: input.roomId,
        userId: input.userId,
        title: input.title,
        startsAt,
        endsAt,
      },
      tx,
    );
  });
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
