import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { createTestApp, resetDb } from './helpers/app.js';

const HOUR = 3_600_000;

function inHours(hours: number): string {
  return new Date(Date.now() + hours * HOUR).toISOString();
}

describe('bookings', () => {
  let app: FastifyInstance;
  let roomId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    const room = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Aurora', capacity: 6 },
    });
    roomId = room.json().id;
    const user = await app.inject({
      method: 'POST',
      url: '/users',
      payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
    });
    userId = user.json().id;
  });

  async function book(startHours: number, endHours: number, title = 'Sync') {
    return app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, title, startsAt: inHours(startHours), endsAt: inHours(endHours) },
    });
  }

  async function post(payload: Record<string, unknown>) {
    return app.inject({ method: 'POST', url: '/bookings', payload });
  }

  async function patch(id: string, payload: Record<string, unknown>) {
    return app.inject({ method: 'PATCH', url: `/bookings/${id}`, payload });
  }

  it('creates a booking', async () => {
    const response = await book(24, 25);
    expect(response.statusCode).toBe(201);
    expect(response.json().status).toBe('ACTIVE');
  });

  it('rejects a payload without a title', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects an instant that cannot be parsed', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, title: 'Sync', startsAt: 'yesterday', endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(400);
  });

  it('reads a booking back', async () => {
    const created = await book(24, 25);
    const response = await app.inject({ method: 'GET', url: `/bookings/${created.json().id}` });
    expect(response.statusCode).toBe(200);
    expect(response.json().title).toBe('Sync');
  });

  it('answers 404 for a booking that does not exist', async () => {
    const response = await app.inject({ method: 'GET', url: '/bookings/missing' });
    expect(response.statusCode).toBe(404);
  });

  it('lists bookings inside the page envelope', async () => {
    await book(24, 25);
    await book(30, 31, 'Retro');
    const response = await app.inject({ method: 'GET', url: '/bookings' });
    expect(response.json().data).toHaveLength(2);
    expect(response.json().pagination.total).toBe(2);
  });

  it('filters bookings by room', async () => {
    await book(24, 25);
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId: other.json().id,
        userId,
        title: 'Elsewhere',
        startsAt: inHours(24),
        endsAt: inHours(25),
      },
    });
    const response = await app.inject({ method: 'GET', url: `/bookings?roomId=${roomId}` });
    expect(response.json().data).toHaveLength(1);
  });

  it('updates the title of a booking', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { title: 'Renamed' },
    });
    expect(response.statusCode).toBe(200);
    expect(response.json().title).toBe('Renamed');
  });

  it('cancels a booking', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'POST',
      url: `/bookings/${created.json().id}/cancel`,
    });
    expect(response.statusCode).toBe(200);
    expect(response.json().status).toBe('CANCELLED');
  });

  it('cancelling twice is idempotent', async () => {
    const created = await book(24, 25);
    const url = `/bookings/${created.json().id}/cancel`;
    await app.inject({ method: 'POST', url });
    const response = await app.inject({ method: 'POST', url });
    expect(response.statusCode).toBe(200);
    expect(response.json().status).toBe('CANCELLED');
  });

  it('deletes a booking', async () => {
    const created = await book(24, 25);
    const id = created.json().id;
    expect((await app.inject({ method: 'DELETE', url: `/bookings/${id}` })).statusCode).toBe(204);
    expect((await app.inject({ method: 'GET', url: `/bookings/${id}` })).statusCode).toBe(404);
  });

  it('rejects a booking whose start falls inside an active booking', async () => {
    await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking fully contained in an active booking', async () => {
    await book(24, 25);
    const response = await book(24.1, 24.85, 'Inside');
    expect(response.statusCode).toBe(409);
  });

  it('accepts a booking that starts exactly when another ends', async () => {
    await book(24, 25);
    const response = await book(25, 26, 'Adjacent');
    expect(response.statusCode).toBe(201);
  });

  it('accepts a booking in a slot released by a cancellation', async () => {
    const first = await book(24, 25);
    await app.inject({ method: 'POST', url: `/bookings/${first.json().id}/cancel` });
    const response = await book(24.5, 25.5, 'Reused slot');
    expect(response.statusCode).toBe(201);
  });

  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that swallows an active one', async () => {
    const first = await book(24, 25);
    const response = await book(23, 26, 'Around');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that ends inside an active one', async () => {
    await book(24, 25);
    const response = await book(23, 24.5, 'Before');
    expect(response.statusCode).toBe(409);
  });

  it('rejects a booking identical to an active one', async () => {
    await book(24, 25);
    const response = await book(24, 25, 'Same');
    expect(response.statusCode).toBe(409);
  });

  it('accepts a booking that ends exactly when another starts', async () => {
    await book(24, 25);
    const response = await book(23, 24, 'Just before');
    expect(response.statusCode).toBe(201);
  });

  it('keeps the same slot free in another room', async () => {
    await book(24, 25);
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    const response = await post({
      roomId: other.json().id,
      userId,
      title: 'Elsewhere',
      startsAt: inHours(24),
      endsAt: inHours(25),
    });
    expect(response.statusCode).toBe(201);
  });

  it('gives the slot to one of two simultaneous requests', async () => {
    const [first, second] = await Promise.all([book(24, 25, 'One'), book(24, 25, 'Two')]);
    expect([first.statusCode, second.statusCode].sort()).toEqual([201, 409]);
    const listed = await app.inject({ method: 'GET', url: '/bookings' });
    expect(listed.json().data).toHaveLength(1);
  });

  it('rejects a booking that ends before it starts', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a booking with no duration', async () => {
    const response = await book(24, 24, 'Instant');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a booking that starts in the past', async () => {
    const response = await book(-2, -1, 'Yesterday');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('accepts a booking that starts right about now', async () => {
    const response = await book(0, 1, 'Starting now');
    expect(response.statusCode).toBe(201);
  });

  it('rejects a booking for a room that does not exist', async () => {
    const response = await post({
      roomId: 'missing-room',
      userId,
      title: 'Sync',
      startsAt: inHours(24),
      endsAt: inHours(25),
    });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.code).toBe('NOT_FOUND');
  });

  it('rejects a booking for a user that does not exist', async () => {
    const response = await post({
      roomId,
      userId: 'missing-user',
      title: 'Sync',
      startsAt: inHours(24),
      endsAt: inHours(25),
    });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.code).toBe('NOT_FOUND');
  });

  it('stores nothing when a booking is refused', async () => {
    await post({ roomId, userId, title: 'Sync', startsAt: inHours(25), endsAt: inHours(24) });
    const response = await app.inject({ method: 'GET', url: '/bookings' });
    expect(response.json().pagination.total).toBe(0);
  });

  it('rejects an update that moves a booking onto an active one', async () => {
    const first = await book(24, 25);
    const second = await book(30, 31, 'Second');
    const response = await patch(second.json().id, {
      startsAt: inHours(24.5),
      endsAt: inHours(25.5),
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects an update that moves a booking into an occupied room', async () => {
    await book(24, 25);
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    const elsewhere = await post({
      roomId: other.json().id,
      userId,
      title: 'Elsewhere',
      startsAt: inHours(24),
      endsAt: inHours(25),
    });
    const response = await patch(elsewhere.json().id, { roomId });
    expect(response.statusCode).toBe(409);
  });

  it('lets a booking keep its own slot while being updated', async () => {
    const created = await book(24, 25);
    const response = await patch(created.json().id, { endsAt: inHours(26) });
    expect(response.statusCode).toBe(200);
  });

  it('rejects an update that leaves the booking ending before it starts', async () => {
    const created = await book(24, 25);
    const response = await patch(created.json().id, { endsAt: inHours(23) });
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects an update that moves a booking into the past', async () => {
    const created = await book(24, 25);
    const response = await patch(created.json().id, { startsAt: inHours(-2) });
    expect(response.statusCode).toBe(400);
  });

  it('rejects an update pointing at a room that does not exist', async () => {
    const created = await book(24, 25);
    const response = await patch(created.json().id, { roomId: 'missing-room' });
    expect(response.statusCode).toBe(404);
  });

  it('rejects an update pointing at a user that does not exist', async () => {
    const created = await book(24, 25);
    const response = await patch(created.json().id, { userId: 'missing-user' });
    expect(response.statusCode).toBe(404);
  });

  it('lets a cancelled booking be moved onto an active slot', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Second');
    await app.inject({ method: 'POST', url: `/bookings/${second.json().id}/cancel` });
    const response = await patch(second.json().id, {
      startsAt: inHours(24),
      endsAt: inHours(25),
    });
    expect(response.statusCode).toBe(200);
  });
});
